// Renders the commitwork reference document as markdown (bin/reference.mjs render).
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { render } from '../reference.mjs';

const run = (o = {}, m = {}) => render({
  cli: { exits: [], doc: null }, commands: [], env: [], ...o,
  manifest: { checkKeys: [], topKeys: [], lanes: [], checkCount: 0, schemaFound: true, ...m },
}).split('\n');
const part = (L, from, to) => L.slice(L.indexOf(from), L.indexOf(to));

const EMPTY = [
  '# Reference', '',
  '<!-- Generated by bin/reference.mjs \u2014 do not hand-edit; run `node bin/reference.mjs` to refresh. -->', '',
  'Every command, `CW_*` environment variable and lane manifest key, read from the source tree by',
  '`bin/reference.mjs`. Descriptions are copied from header comments and the manifest schema; where',
  'none exists the entry says `undocumented` and is counted below, rather than being described here.',
  'Exit codes are what each header declares (full tables in [EXIT-CODES.md](EXIT-CODES.md)), not',
  'verified against the code. Check definitions are indexed in [MANIFEST-MAP.md](MANIFEST-MAP.md).', '',
  '| Surface | Total | Documented | Undocumented |', '|---|---:|---:|---:|',
  '| Commands (a usage line in the header) | 0 | 0 | 0 |',
  '| Exit codes (declared in the header) | 0 | 0 | 0 |',
  '| `CW_*` environment variables (described in an `env` header) | 0 | 0 | 0 |',
  '| Lane manifest check keys in use (described in the schema) | 0 | 0 | 0 |', '',
  'Commands are the population of `bin/exit-codes.mjs`: top-level `bin/`, `monitor/` and `cra/`',
  'entry points, plus the `commitwork` subcommands.', '',
  '## `commitwork`', '',
  '`bin/commitwork.mjs` has no `usage()`; its subcommands are undocumented.', '',
  'Exit codes:', '', '',
  '## Environment variables', '',
  '0 `CW_*` names read by tracked non-test sources: 0 by name, and',
  '0 indirect (quoted in a file that reads the environment by a computed key, so the read',
  'is likely but not shown). At most 6 readers are listed per name. A description is taken from',
  "a reader's `env` header section when one has it, otherwise from another file's, which is named.", '',
  '| Variable | Read | Read by | Description |', '|---|---|---|---|', '',
  '## Manifest keys', '',
  'Lane manifests (`$schema` is `manifest.schema.json`): none; 0 checks in all.',
  'A nested key is written `parent.child`. A key the schema declares and no check uses is listed with 0.', '',
  '### Check keys', '', '| Key | Checks | Description |', '|---|---:|---|', '',
  '### Manifest-level keys', '', '| Key | Manifests | Description |', '|---|---:|---|',
];

test('an empty source tree renders the full document with no command groups and no lanes', () => {
  assert.deepEqual(run(), EMPTY);
});

test('only declared exit statuses count as documented and commands are grouped by directory', () => {
  const L = run({
    cli: {
      exits: [
        { name: 'E1', status: 'declared', entries: [{ code: 1, meaning: 'ok' }], via: true, source: 's' },
        { name: 'E2', status: 'undeclared', via: false },
      ],
      doc: null,
    },
    commands: [
      { name: 'bin/a', usage: ['a run'], options: ['-q', 'x`y'], status: 'prose', summary: 'Runs\n  a.' },
      { name: 'monitor/m', usage: [], options: [], status: 'undeclared', summary: null },
    ],
  });
  assert.deepEqual(L.slice(12, 14), [
    '| Commands (a usage line in the header) | 2 | 1 | 1 |',
    '| Exit codes (declared in the header) | 4 | 1 | 3 |',
  ]);
  assert.deepEqual(part(L, '## `commitwork`', '## Environment variables'), [
    '## `commitwork`', '',
    '`bin/commitwork.mjs` has no `usage()`; its subcommands are undocumented.', '',
    'Exit codes:', '',
    '- `E1`: 1 ok (declared in `s`)',
    '- `E2`: undeclared', '',
    '## bin/', '', '### `bin/a`', '', 'Runs a.', '',
    '- Usage: `a run`', '- Option: `-q`', '- Option: `` x`y ``',
    '- Exit: stated in the header in a form not tabulated (prose)', '',
    '## monitor/', '', '### `monitor/m`', '',
    '- Usage: undocumented', '- Exit: undeclared', '',
  ]);
});

test('a commitwork usage doc renders usage and option tables and lists its environment only when present', () => {
  const doc = {
    commands: [{ usage: 'cw run', desc: 'Runs it' }, { usage: 'cw a|b', desc: '' }],
    options: [{ usage: '-v', desc: 'verbose' }],
    env: ['CW_X'],
  };
  const tables = [
    '## `commitwork`', '', 'From `usage()` in `bin/commitwork.mjs`.', '',
    '| Usage | Description |', '|---|---|', '| `cw run` | Runs it |', '| `cw a\\|b` | undocumented |', '',
    '| Option | Description |', '|---|---|', '| `-v` | verbose |', '',
  ];
  assert.deepEqual(part(run({ cli: { exits: [], doc } }), '## `commitwork`', 'Exit codes:'), [...tables, 'Environment: CW_X', '']);
  assert.deepEqual(part(run({ cli: { exits: [], doc: { ...doc, env: [] } } }), '## `commitwork`', 'Exit codes:'), tables);
});

test('indirect environment reads are counted apart and a description from a non-reader names its file', () => {
  const L = run({
    env: [
      { name: 'CW_A', how: 'indirect', readers: ['a.mjs'], description: null },
      { name: 'CW_B', how: 'direct', readers: ['b.mjs'], description: { text: 'Bee var', from: 'b.mjs' } },
      { name: 'CW_C', how: 'direct', readers: ['c.mjs', 'd.mjs'], description: { text: 'See var', from: 'x.mjs' } },
    ],
  });
  assert.equal(L[14], '| `CW_*` environment variables (described in an `env` header) | 3 | 2 | 1 |');
  assert.deepEqual(part(L, '## Environment variables', '## Manifest keys'), [
    '## Environment variables', '',
    '3 `CW_*` names read by tracked non-test sources: 2 by name, and',
    '1 indirect (quoted in a file that reads the environment by a computed key, so the read',
    'is likely but not shown). At most 6 readers are listed per name. A description is taken from',
    "a reader's `env` header section when one has it, otherwise from another file's, which is named.", '',
    '| Variable | Read | Read by | Description |', '|---|---|---|---|',
    '| `CW_A` | indirect | `a.mjs` | undocumented |',
    '| `CW_B` | direct | `b.mjs` | Bee var |',
    '| `CW_C` | direct | `c.mjs`, `d.mjs` | See var (`x.mjs`) |', '',
  ]);
});

test('six readers are all listed while a seventh is summarised as one more', () => {
  const files = (n) => Array.from({ length: n }, (_, i) => 'f' + i + '.mjs');
  const shown = files(6).map((f) => '`' + f + '`').join(', ');
  const L = run({
    env: [
      { name: 'CW_S', how: 'direct', readers: files(6), description: null },
      { name: 'CW_T', how: 'direct', readers: files(7), description: null },
    ],
  });
  assert.deepEqual(part(L, '| Variable | Read | Read by | Description |', '## Manifest keys'), [
    '| Variable | Read | Read by | Description |', '|---|---|---|---|',
    '| `CW_S` | direct | ' + shown + ' | undocumented |',
    '| `CW_T` | direct | ' + shown + ' and 1 more | undocumented |', '',
  ]);
});

test('only check keys used at least once are counted and a missing schema is noted', () => {
  const L = run({}, {
    checkKeys: [
      { key: 'k0', uses: 0, description: 'Zero' },
      { key: 'k1', uses: 1, description: 'One' },
      { key: 'k2', uses: 2, description: null },
    ],
    topKeys: [{ key: 'lane', uses: 3, description: 'Lane name' }, { key: 'x', uses: 1, description: null }],
    lanes: [{ file: 'a.json', checks: 2 }, { file: 'b.json', checks: 1 }],
    checkCount: 3,
    schemaFound: false,
  });
  assert.equal(L[15], '| Lane manifest check keys in use (described in the schema) | 2 | 1 | 1 |');
  assert.deepEqual(L.slice(L.indexOf('## Manifest keys')), [
    '## Manifest keys', '',
    '`schema/manifest.schema.json` is absent, so no key has a description.', '',
    'Lane manifests (`$schema` is `manifest.schema.json`): `a.json` (2), `b.json` (1); 3 checks in all.',
    'A nested key is written `parent.child`. A key the schema declares and no check uses is listed with 0.', '',
    '### Check keys', '', '| Key | Checks | Description |', '|---|---:|---|',
    '| `k0` | 0 | Zero |', '| `k1` | 1 | One |', '| `k2` | 2 | undocumented |', '',
    '### Manifest-level keys', '', '| Key | Manifests | Description |', '|---|---:|---|',
    '| `lane` | 3 | Lane name |', '| `x` | 1 | undocumented |',
  ]);
});
